<script setup lang="ts">
import {computed,ref} from 'vue';
import {studioPlanWords,studioWords,fillWords} from '../../utils/studio-content';
import {onShow,onHide,onUnload} from '@dcloudio/uni-app';
import StudioAdminShell from '../../components/StudioAdminShell.vue';
import {useStudioNative} from '../../utils/studio-native';
import {adminCall,adminError,goAdmin,today} from '../../utils/studio-admin';
import {adminView} from '../../utils/studio-admin-cache';
import copy from '../../../../05_studio/src/content/workbench.json';
const {language,keyboardOpen,shellStyle,say,changeLanguage}=useStudioNative();
type State={experience:string;days:any[];start:string;selected:string;loaded:boolean};
const view=adminView<State>('calendar'),saved=view.snapshot;
const days=ref<any[]>(saved?.days||[]),start=ref(saved?.start||today()),selected=ref(saved?.selected||today()),loaded=ref(saved?.loaded||false),busy=ref(false),error=ref('');let sequence=0;
const experience=ref(saved?.experience||'all');
const patchWords=(key:string)=>say(studioWords('patch',key));
const gift=(count:number)=>fillWords(studioWords('promotion','gift_count'),language.value,{v0:count});
const day=computed(()=>days.value.find(d=>d.date===selected.value));
const ordered=computed(()=>[...(day.value?.bookings||[])].sort((a,b)=>a.start.localeCompare(b.start)||a.name.localeCompare(b.name)));
const colors=['#759aa9','#938ab8','#b594b7','#b9a372','#87a58c','#ad8991'];
function color(id:string){return colors[[...id].reduce((sum,c)=>sum+c.charCodeAt(0),0)%colors.length];}
const label=(key:string)=>say((copy as Record<string,string[]>)[key]||copy.all);
const remember=()=>view.save({experience:experience.value,days:days.value,start:start.value,selected:selected.value,loaded:loaded.value});
async function load(force=true){if(!view.valid()){days.value=[];loaded.value=false;}if(!force&&(busy.value||view.fresh()))return;const n=++sequence,revision=view.begin();busy.value=true;error.value='';try{const result=await adminCall<{days:any[]}>('/manage/reservation-timetable',{start:start.value,experience:experience.value});if(n===sequence){days.value=result.days;if(!days.value.some(d=>d.date===selected.value))selected.value=days.value[0]?.date||start.value;loaded.value=true;view.loaded(revision);remember();}}catch(e){if(n===sequence){error.value=adminError(e,say);if(!view.valid()){days.value=[];loaded.value=false;}}}finally{if(n===sequence)busy.value=false;}}
onShow(()=>void load(false));onHide(remember);onUnload(()=>{remember();sequence++;});
</script>
<template><StudioAdminShell :title="say(copy.calendar)" active="reservations" back :language="language" :shell-style="shellStyle" :keyboard-open="keyboardOpen" :busy="busy&&!loaded" :error="error" @refresh="load()" @language="changeLanguage"><view class="admin-filters" :aria-label="patchWords('filter')"><button v-for="kind in ['all','beads','patch']" :key="kind" :class="{chosen:experience===kind}" hover-class="admin-pressed" :hover-start-time="0" :hover-stay-time="180" @tap="experience=kind;load()">{{patchWords(kind)}}</button></view><text v-if="experience==='patch'" class="admin-muted">{{patchWords('capacity')}}</text><picker mode="date" :value="start" @change="start=$event.detail.value;load()"><view class="admin-input">{{say(copy.date)}} · {{start}}</view></picker><view class="native-calendar-days"><button v-for="d in days" :key="d.date" :class="{chosen:d.date===selected}" hover-class="admin-pressed" :hover-start-time="0" :hover-stay-time="180" @tap="selected=d.date"><text>{{d.date.slice(5)}}</text><text class="admin-muted">{{d.bookings.length}}</text></button></view><view v-if="day" class="admin-row"><text class="admin-name">{{day.date}}</text><text class="admin-muted">{{day.open}}–{{day.close}}</text></view><text class="admin-muted">{{say(copy.timezone)}}</text><view class="native-calendar-bookings"><button v-for="booking in ordered" :key="booking.id" class="admin-card admin-stack native-calendar-booking" :style="{borderLeftColor:color(booking.id)}" hover-class="admin-pressed" :hover-start-time="0" :hover-stay-time="180" @tap="goAdmin('-reservation','id='+booking.id)"><view class="admin-row"><text class="admin-name">{{booking.name}}</text><text class="admin-badge">{{label(booking.status)}}</text></view><view class="admin-row"><text>{{booking.start}}–{{booking.end}}</text><text>{{say(copy.guests).replace('{count}',String(booking.guests))}}</text></view><text class="admin-muted">{{say(studioPlanWords(booking.plan))}}</text><text v-if="booking.patch_gift_guests>0" class="admin-patch-gift">{{gift(booking.patch_gift_guests)}}</text><text v-if="booking.note" class="admin-muted">{{booking.note}}</text></button></view><view v-if="!busy&&!ordered.length" class="admin-empty">{{say(copy.empty)}}</view></StudioAdminShell></template>
<style scoped>.native-calendar-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;margin:14px 0 20px}.native-calendar-days button{display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center;background:white;border:1px solid #dfe8ed;border-radius:9px;padding:10px 3px;min-height:52px;font-size:12px}.native-calendar-days .chosen{background:#dfedf5;border-color:#97b3c4}.native-calendar-bookings{margin-top:14px}.native-calendar-booking{border-left-width:4px;display:flex;width:100%;text-align:left}.native-calendar-booking>.admin-row{width:100%}@media(max-width:350px){.native-calendar-days{grid-template-columns:repeat(4,minmax(0,1fr))}}</style>
